-- A change of official school level requires confirming the matching NEIS school again.
create function private.reset_school_info_for_new_level() returns trigger
language plpgsql set search_path='' as $$
begin
  new.neis_office_code := null;
  new.neis_school_code := null;
  new.road_address := null;
  new.homepage_url := null;
  new.foundation_day := null;
  new.weather_nx := null;
  new.weather_ny := null;
  return new;
end $$;
revoke all on function private.reset_school_info_for_new_level() from public, anon, authenticated;
create trigger reset_school_info_for_new_level before update of school_type on public.schools
  for each row when (old.school_type is distinct from new.school_type and old.neis_school_code is not null)
  execute function private.reset_school_info_for_new_level();
